create type public.cloudflare_connection_status as enum ('NOT_CONFIGURED','CONNECTED','ERROR'); create type public.cloudflare_deployment_status as enum ('NOT_CONNECTED','PENDING','DEPLOYED','ERROR');
create table public.cloudflare_accounts(id uuid primary key default gen_random_uuid(), account_reference text, display_name text, status public.cloudflare_connection_status not null default 'NOT_CONFIGURED', last_checked_at timestamptz, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()));
create table public.cloudflare_zones(id uuid primary key default gen_random_uuid(), account_id uuid references public.cloudflare_accounts(id) on delete cascade, website_id uuid not null unique references public.websites(id) on delete cascade, tenant_id uuid not null references public.customer_accounts(id) on delete cascade, zone_reference text, domain text not null, status text, ssl_status text, last_checked_at timestamptz, created_at timestamptz not null default timezone('utc',now()), updated_at timestamptz not null default timezone('utc',now()));
create table public.cloudflare_deployments(id uuid primary key default gen_random_uuid(), website_id uuid not null references public.websites(id) on delete cascade, tenant_id uuid not null references public.customer_accounts(id) on delete cascade, environment text not null default 'production', status public.cloudflare_deployment_status not null default 'NOT_CONNECTED', deployment_reference text, deployed_at timestamptz, last_checked_at timestamptz, safe_error text, created_at timestamptz not null default timezone('utc',now()));
create table public.cloudflare_operation_logs(id uuid primary key default gen_random_uuid(), tenant_id uuid not null references public.customer_accounts(id) on delete cascade, website_id uuid references public.websites(id) on delete cascade, operation_type text not null, status text not null, safe_error text, started_at timestamptz, completed_at timestamptz, created_at timestamptz not null default timezone('utc',now()));
create or replace function public.validate_cloudflare_zone_scope() returns trigger language plpgsql set search_path='' as $$ declare website_tenant uuid; begin if auth.uid() is null or not public.is_master_admin() then raise exception 'Only Master Admin can manage Cloudflare infrastructure'; end if; select tenant_id into website_tenant from public.websites where id=new.website_id; if website_tenant is null then raise exception 'Website is not available'; end if; new.tenant_id:=website_tenant; return new; end; $$;
create trigger cloudflare_zones_validate_scope before insert or update on public.cloudflare_zones for each row execute function public.validate_cloudflare_zone_scope();
alter table public.cloudflare_accounts enable row level security; alter table public.cloudflare_zones enable row level security; alter table public.cloudflare_deployments enable row level security; alter table public.cloudflare_operation_logs enable row level security;
create policy cloudflare_accounts_master_manage on public.cloudflare_accounts for all to authenticated using(public.is_master_admin()) with check(public.is_master_admin()); create policy cloudflare_zones_customer_select on public.cloudflare_zones for select to authenticated using(tenant_id=public.current_tenant_id()); create policy cloudflare_zones_master_manage on public.cloudflare_zones for all to authenticated using(public.is_master_admin()) with check(public.is_master_admin()); create policy cloudflare_deployments_customer_select on public.cloudflare_deployments for select to authenticated using(tenant_id=public.current_tenant_id()); create policy cloudflare_deployments_master_manage on public.cloudflare_deployments for all to authenticated using(public.is_master_admin()) with check(public.is_master_admin()); create policy cloudflare_operation_logs_master_select on public.cloudflare_operation_logs for select to authenticated using(public.is_master_admin());
revoke execute on function public.validate_cloudflare_zone_scope() from public,authenticated;
